class Kedi:
  def ses(self): print('Miyav')
class Kopek:
  def ses(self): print('Hav')

hayvanlar = [Kedi(), Kopek(), Kedi()]

for h in hayvanlar:
  h.ses() # Hangisi olduğuna bakılmaksızın çalışır

class Sekil:
  def alan(self): pass

class Kare(Sekil):
  def alan(self): return 'Karenin alanı'

class Daire(Sekil):
  def alan(self): return 'Dairenin alanı'

s1 = Kare()
s2 = Daire()
print(s1.alan())
print(s2.alan())

class Kus: 
  def uc(self): print('Kuş uçuyor.')
class Ucak:
  def uc(self): print('Uçak uçuyor.')

def ucus_testi(nesne):
  nesne.uc() # Nesnenin uc() metodu varsa sorunsuz çalışır

ucus_testi(Kus())
ucus_testi(Ucak())
